using System;
using System.Collections.Generic;
using UnityEngine;

namespace Brainwash
{
    // Low-poly models generated by art/models (Blender). Every FBX in
    // Resources/Models paints its faces from one shared palette texture; the
    // first four palette cells are tinted with the entity's own colour, so a
    // "red imp" and an "orange imp" share one mesh. Objects whose names end in
    // "_Glow" (eyes, coals, acid sacs) are drawn unlit. When a model is missing
    // the callers fall back to their primitive builders.
    public static class ModelLibrary
    {
        [Serializable] sealed class PaletteCell { public string name; public int[] rgb; }
        [Serializable] sealed class PaletteFile { public int cellPixels = 16; public int grid = 8; public int[] tintCells; public PaletteCell[] cells; }

        static readonly Dictionary<string, GameObject> prefabs = new Dictionary<string, GameObject>();
        static readonly Dictionary<Color32, Material[]> materials = new Dictionary<Color32, Material[]>();
        static readonly Dictionary<string, int> cellIndex = new Dictionary<string, int>();
        static PaletteFile palette;
        static bool paletteLoaded;

        public static bool Enabled = true;

        public static GameObject Prefab(string id)
        {
            if (!Enabled || string.IsNullOrEmpty(id)) return null;
            if (!prefabs.TryGetValue(id, out var prefab))
            {
                prefab = Resources.Load<GameObject>("Models/" + id);
                prefabs[id] = prefab;
            }
            return prefab != null && Palette() != null ? prefab : null;
        }

        public static bool Has(string id) => Prefab(id) != null;

        // Instantiates the model under parent (local identity) with tinted materials.
        public static GameObject Spawn(string id, Transform parent, Color tint)
        {
            var prefab = Prefab(id);
            if (prefab == null) return null;
            var go = UnityEngine.Object.Instantiate(prefab, parent, false);
            go.name = id + " model";
            go.transform.localPosition = Vector3.zero; go.transform.localRotation = Quaternion.identity;
            // Bones are posed in code; an imported Animator would only cost time.
            var animator = go.GetComponent<Animator>(); if (animator != null) UnityEngine.Object.Destroy(animator);
            Paint(go, tint);
            return go;
        }

        public static void Paint(GameObject go, Color tint)
        {
            var set = Materials(tint);
            foreach (var renderer in go.GetComponentsInChildren<Renderer>(true))
            {
                bool glow = renderer.name.EndsWith("_Glow", StringComparison.Ordinal);
                var mats = renderer.sharedMaterials;
                if (mats.Length == 0) mats = new Material[1];
                for (int i = 0; i < mats.Length; i++) mats[i] = glow ? set[1] : set[0];
                renderer.sharedMaterials = mats;
                renderer.shadowCastingMode = glow ? UnityEngine.Rendering.ShadowCastingMode.Off : UnityEngine.Rendering.ShadowCastingMode.On;
                if (renderer is SkinnedMeshRenderer skinned) skinned.updateWhenOffscreen = true;
            }
        }

        // The palette colour of a named cell (for effects such as debris).
        public static Color Cell(string name, Color fallback)
        {
            var p = Palette();
            if (p == null || !cellIndex.TryGetValue(name, out int i)) return fallback;
            var rgb = p.cells[i].rgb;
            return new Color32((byte)rgb[0], (byte)rgb[1], (byte)rgb[2], 255);
        }

        // Base, shade, light and deep variants of an entity colour; mirrors
        // tint_colors() in art/models/bwkit.py.
        public static Color32[] TintCells(Color tint)
        {
            Color c = tint; c.a = 1;
            return new Color32[] { c, Scaled(c, .62f), Color.Lerp(c, Color.white, .35f), Scaled(c, .38f) };
        }

        static Color Scaled(Color c, float k) => new Color(c.r * k, c.g * k, c.b * k, 1);

        [Serializable] sealed class ModelInfo { public string id; public float height; public string gait; public float[] size; public float[] center; }
        [Serializable] sealed class ModelIndex { public ModelInfo[] models; }
        static Dictionary<string, ModelInfo> index;

        static ModelInfo Info(string id)
        {
            if (index == null)
            {
                index = new Dictionary<string, ModelInfo>();
                var asset = Resources.Load<TextAsset>("Models/models");
                if (asset != null)
                    try { foreach (var info in JsonUtility.FromJson<ModelIndex>(asset.text)?.models ?? Array.Empty<ModelInfo>()) index[info.id] = info; }
                    catch (ArgumentException) { }
            }
            return index.TryGetValue(id, out var found) ? found : null;
        }

        // The height the model was built at (metres), for scaling to an entity.
        public static float Height(string id, float fallback) { var info = Info(id); return info != null && info.height > .01f ? info.height : fallback; }
        public static string Gait(string id) => Info(id)?.gait;
        // Bounding box of the model in Unity axes, and its centre.
        public static Vector3 Size(string id, Vector3 fallback) { var s = Info(id)?.size; return s != null && s.Length == 3 ? new Vector3(s[0], s[1], s[2]) : fallback; }
        public static Vector3 Center(string id) { var c = Info(id)?.center; return c != null && c.Length == 3 ? new Vector3(c[0], c[1], c[2]) : Vector3.zero; }

        static PaletteFile Palette()
        {
            if (paletteLoaded) return palette;
            paletteLoaded = true;
            var asset = Resources.Load<TextAsset>("Models/palette");
            if (asset == null) return null;
            try
            {
                palette = JsonUtility.FromJson<PaletteFile>(asset.text);
                if (palette?.cells == null || palette.cells.Length < palette.grid * palette.grid) palette = null;
                else for (int i = 0; i < palette.cells.Length; i++) cellIndex[palette.cells[i].name] = i;
            }
            catch (ArgumentException) { palette = null; }
            return palette;
        }

        static Material[] Materials(Color tint)
        {
            Color32 key = tint; key.a = 255;
            if (materials.TryGetValue(key, out var set) && set[0] != null) return set;
            var texture = BuildTexture(key);
            var lit = new Material(Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Standard")) { name = "Palette " + key };
            lit.mainTexture = texture;
            if (lit.HasProperty("_BaseMap")) lit.SetTexture("_BaseMap", texture);
            if (lit.HasProperty("_BaseColor")) lit.SetColor("_BaseColor", Color.white);
            lit.color = Color.white;
            if (lit.HasProperty("_Smoothness")) lit.SetFloat("_Smoothness", .12f);
            if (lit.HasProperty("_Glossiness")) lit.SetFloat("_Glossiness", .12f);
            // Sprites/Default is unlit and always included in builds (the demo effects use it too).
            var glow = new Material(Shader.Find("Sprites/Default") ?? Shader.Find("Universal Render Pipeline/Unlit")) { name = "Palette glow " + key, mainTexture = texture, color = Color.white };
            set = new[] { lit, glow };
            materials[key] = set;
            return set;
        }

        static Texture2D BuildTexture(Color32 tint)
        {
            var p = Palette();
            int cell = p.cellPixels, grid = p.grid, size = cell * grid;
            var texture = new Texture2D(size, size, TextureFormat.RGBA32, false) { name = "Palette " + tint, filterMode = FilterMode.Point, wrapMode = TextureWrapMode.Clamp };
            var pixels = new Color32[size * size];
            var tints = TintCells(tint);
            for (int i = 0; i < grid * grid; i++)
            {
                var rgb = p.cells[i].rgb;
                Color32 color = new Color32((byte)rgb[0], (byte)rgb[1], (byte)rgb[2], 255);
                if (p.tintCells != null) { int t = Array.IndexOf(p.tintCells, i); if (t >= 0 && t < tints.Length) color = tints[t]; }
                int col = i % grid, row = i / grid;
                // Row 0 is the top of the image; Unity textures start at the bottom.
                int y0 = (grid - 1 - row) * cell, x0 = col * cell;
                for (int y = 0; y < cell; y++)
                    for (int x = 0; x < cell; x++) pixels[(y0 + y) * size + x0 + x] = color;
            }
            texture.SetPixels32(pixels);
            texture.Apply(false, true);
            return texture;
        }
    }
}
